#include <iostream>
int main() {
    char op = '+';
    switch (op) {
        case '+': std::cout << "Cong\n"; break;
        case '-': std::cout << "Tru\n"; break;
        default:  std::cout << "Khac\n";
    }
}

#include <iostream>
int main() {
    for (int i = 1; i <= 5; ++i) {
        if (i == 3) continue; // Bỏ qua số 3
        if (i == 5) break;    // Dừng hẳn ở 5
        std::cout << i << ' '; // In: 1 2 4
    }
}

